"""Cuaderno del estudiante, 1.º medio Lengua y Literatura, OA 01 (trayectoria lectora autónoma) y OA 02 (experiencia humana).

Los títulos, fichas y textos son originales e inventados («de ejemplo»); cada ejercicio trae escritos los textos y datos que necesita.
Nota: los títulos de las clases del repositorio ordenan cada OA en pasos (propósito, evidencia, recursos, contraste, contexto,
lectura propia); este cuaderno los sigue y reparte entre ellos los contenidos del OA oficial.
Aquí se definen los ayudantes `E`, `L`, `task`, `arith`, `MAT` que reutilizan los otros módulos le_m1_*.
"""
from __future__ import annotations

from student_lessons import arith, ex, register

OA1 = "LE1M OA 01"
OA2 = "LE1M OA 02"
E = ex

MAT = "Este cuaderno, lápiz y los textos y datos escritos en cada ejercicio. No necesitas libros especiales ni internet."


def task(statement, example, criteria, evidence, errors, feedback):
    return {"statement": statement, "example": example, "criteria": criteria, "evidence": evidence, "errors": errors, "feedback": feedback}


def L(oa, n, use, prior, explain, vocab, worked, mistakes, tiers, ctx, sc, open_task, reinforce, extend, materials=MAT):
    register(
        oa, n, materials=materials, use=use, prior=prior, explain=explain, vocab=vocab,
        worked=[{"title": t, "problem": p, "steps": s, "answer": a} for t, p, s, a in worked],
        mistakes=[{"wrong": w, "why": y, "fix": f} for w, y, f in mistakes],
        tiers=dict(zip(("recovery", "understand", "apply", "reason", "challenge"), tiers)),
        context=ctx, selfcheck=sc, open_task=task(*open_task), reinforce=reinforce, extend=extend,
    )


# Seis fichas de lectura inventadas (de ejemplo) para las clases de OA 01
F1 = "«El faro de piedra» (novela juvenil de misterio, 280 páginas)"
F2 = "«Guía para entender el clima» (libro de divulgación científica, 96 páginas)"
F3 = "«Pasos sobre la nieve» (cuento, 12 páginas)"
F4 = "«Voces del puerto» (poemario, 40 páginas)"
F5 = "«La balanza» (obra de teatro, 48 páginas)"
F6 = "«Cartas desde el sur» (crónica de viaje en forma de cartas, con datos de lugares y costumbres, 64 páginas)"
FICHAS = f"{F1}; {F2}; {F3}; {F4}; {F5}; {F6}"

